-- Samain isi SPJ (Surat Perjanjian Jamaah, dokumen_pasal.dokumen = 'jamaah')
-- di dev & prod dengan versi lokal yang sudah final (diminta user 2026-10-16).
-- Isi SPJ sebelumnya cuma dari seed awal / editan admin per-server, gak pernah
-- lewat migrasi, jadi dev & main ketinggalan dibanding lokal.
--
-- Pasal SPJ lama dihapus dulu supaya nomor pasal yang gak ada di versi lokal
-- gak nyangkut. Booking lama aman: yang dicetak tetap dari
-- dokumen_pasal_snapshot, bukan dari tabel ini.
DELETE FROM dokumen_pasal WHERE dokumen = 'jamaah';

INSERT INTO dokumen_pasal (dokumen, nomor, tipe, judul, isi) VALUES
  ('jamaah', 1, 'pasal', 'Objek Perjanjian', '- Objek Perjanjian ini adalah penyelenggaraan Perjalanan Ibadah Umroh oleh **PENYELENGGARA** kepada **JAMAAH** sesuai dengan paket perjalanan yang dipilih dan disepakati.\n- **PENYELENGGARA** merupakan Penyelenggara Perjalanan Ibadah Umrah (PPIU) berizin resmi dan menyelenggarakan perjalanan umroh sesuai dengan ketentuan peraturan perundang-undangan yang berlaku.'),
  ('jamaah', 2, 'pasal', 'Biaya dan Pembayaran', '- Total biaya paket umroh yang wajib dibayar **JAMAAH** ditetapkan sesuai paket yang dipilih dan tercantum dalam formulir pendaftaran/invoice yang menjadi satu kesatuan dengan Perjanjian ini.\n- **JAMAAH** membayar Uang Muka (DP) pada saat pendaftaran. Uang Muka (DP) ini **TIDAK DAPAT DITARIK KEMBALI** dengan alasan apapun dan hanya dapat dipergunakan sebagai pengurang biaya pada saat pelunasan.\n- Sisa pelunasan pembayaran wajib diselesaikan paling lambat H-30 sebelum tanggal keberangkatan.\n- Seluruh pembayaran dilakukan melalui transfer ke rekening resmi **PENYELENGGARA** sebagai berikut:\n  - Nama Bank: Bank Syariah Indonesia (BSI)\n  - No. Rekening: 7133-0541-24\n  - Atas Nama: Alkhalid Jaya Megah\n- Pembayaran yang dilakukan di luar rekening resmi tersebut di atas bukan merupakan tanggung jawab **PENYELENGGARA**.'),
  ('jamaah', 3, 'pasal', 'Cakupan Paket', '**Biaya Paket TERMASUK**\n- Tiket pesawat Pulang-Pergi (PP), transportasi, dan akomodasi.\n- Visa umroh dan asuransi perjalanan.\n- Perlengkapan umroh dan handling.\n- Tour leader dan muthowif.\n- Makan 3 (tiga) kali sehari.\n- Bimbingan Manasik.\n\n**Biaya Paket TIDAK TERMASUK**\n- Tiket dan asuransi perjalanan domestik menuju/dari Jakarta.\n- Pengeluaran pribadi dan kelebihan bagasi (excess baggage).\n- Pembuatan paspor dan vaksinasi wajib (termasuk vaksin meningitis dan polio).\n- Akomodasi/transportasi saat pelaksanaan manasik.\n- Tambahan biaya akibat penyesuaian regulasi/kebijakan pemerintah.'),
  ('jamaah', 4, 'pasal', 'Hak dan Kewajiban', '**Hak dan Kewajiban PENYELENGGARA**\n- Berhak menerima pembayaran biaya perjalanan ibadah umroh dari **JAMAAH** serta menetapkan peraturan teknis perjalanan.\n- Wajib mengurus seluruh kebutuhan perjalanan umroh (visa, tiket, hotel, transportasi) serta memberikan bimbingan ibadah sesuai paket yang disepakati.\n- Berhak melakukan penyesuaian jadwal, maskapai, atau akomodasi dalam kondisi Force Majeure demi keselamatan dan kelancaran ibadah.\n\n**Hak dan Kewajiban JAMAAH**\n- Berhak memperoleh pelayanan perjalanan ibadah umroh, bimbingan manasik, dan fasilitas perlengkapan umroh sesuai paket yang disepakati.\n- Wajib melengkapi seluruh dokumen administrasi (Paspor berlaku minimal 6 (enam) bulan, KTP, KK, Kartu Vaksin meningitis dan polio) dan melunasi biaya umroh sesuai ketentuan dan jadwal yang ditetapkan.\n- Wajib mematuhi seluruh peraturan **PENYELENGGARA**, maskapai, hotel, arahan pembimbing, serta hukum di Republik Indonesia dan Kerajaan Arab Saudi.'),
  ('jamaah', 5, 'pasal', 'Pembatalan', '- Apabila **JAMAAH** membatalkan pendaftaran/keberangkatan sebelum pelunasan, Uang Muka (DP) tidak dapat dikembalikan (hangus).\n- Apabila pembatalan dilakukan setelah pelunasan, pengembalian biaya mengikuti ketentuan refund dari pihak maskapai, hotel, dan penyedia layanan lainnya.'),
  ('jamaah', 6, 'pasal', 'Force Majeure dan Penyesuaian Layanan', '- Force Majeure adalah kejadian di luar kendali **PENYELENGGARA**, termasuk tidak terbatas pada bencana alam, wabah penyakit, perang, kebijakan imigrasi/pemerintah, dan pembatalan penerbangan.\n- Dalam hal terjadi kondisi Force Majeure yang mengakibatkan penundaan keberangkatan, **JAMAAH** tidak dapat menuntut ganti rugi atau menyalahkan **PENYELENGGARA**, dan **PENYELENGGARA** akan memberangkatkan **JAMAAH** pada jadwal penyesuaian berikutnya tanpa biaya tambahan.\n- Apabila terjadi penyesuaian biaya akibat perubahan regulasi (seperti fluktuasi kurs mata uang, kenaikan tarif maskapai/hotel, pajak, dan lain-lain), kenaikan harga paket umroh akan diinformasikan kepada **JAMAAH** selambat-lambatnya H-30 sebelum keberangkatan dan sepenuhnya menjadi penambahan biaya yang ditanggung oleh **JAMAAH**.\n- Penyesuaian tipe kamar hotel akibat keterbatasan ketersediaan menjadi wewenang **PENYELENGGARA** dan selisih biaya (jika ada upgrade) dibebankan kepada **JAMAAH**.'),
  ('jamaah', 7, 'pasal', 'Penutup', '- Perjanjian ini dibuat dan ditandatangani dengan sadar, tanpa paksaan dari pihak manapun.\n- Perjanjian ini dibuat dalam rangkap bermaterai cukup, masing-masing memiliki kekuatan hukum yang sama dan mengikat Para Pihak sejak ditandatangani.\n- Hal-hal yang belum diatur akan diselesaikan melalui musyawarah mufakat atau mengikuti kebijakan resmi **PENYELENGGARA**.\n- Apabila timbul perselisihan dan tidak dapat diselesaikan secara musyawarah dalam waktu 30 (tiga puluh) hari, Para Pihak sepakat memilih domisili hukum di Pengadilan Negeri Jakarta Selatan.');
